    public void insert(
        NoYes   _dropEstimated,
        NoYes   _updateReservation)
    {
        InventDim iDimFrom = this.inventDim();
        InventDim iDimQA = InventDim::find(this.inventDimIdQuarantine);
        InventDim iDimQANew;

		if (iDimFrom.LicensePlateId && !iDimQA.LicensePlateId && !iDimQA.wmsLocation().LocProfileId && !iDimFrom.wmsLocation().LocProfileId)
        {
            iDimQA.LicensePlateId = iDimFrom.LicensePlateId;
            iDimQANew = InventDim::findOrCreate(iDimQA);
            this.inventDimIdQuarantine = iDimQANew.inventDimId;
        }

        next insert(_dropEstimated,_updateReservation);
    }
